package numeric

import (
	"fmt"
	"os"
	"sync"
	"sync/atomic"
	"time"
)

// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
type Clock interface {
	Now() time.Time
}

type wallClock struct{}

func (wallClock) Now() time.Time { return time.Now().UTC() }

// Option 配置 [Open] 的行为。
type Option func(*Store)

// WithClock 注入自定义时钟。
func WithClock(c Clock) Option {
	return func(s *Store) { s.now = c.Now }
}

// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
//
// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
// idemIdentity 是幂等作用域（提交人, 请求号）的复合键。两个字段都按调用方
// 给出的完整字符串逐字节参与比较，允许包含 U+0000 与非法 UTF-8 字节
// （后者靠记录中的 identity_raw 兜底字段跨重开保真）。不能用分隔符把两个
// 字段拼成单个字符串：提交人 "a"、请求号 "b\x00c" 与提交人 "a\x00b"、
// 请求号 "c" 在任何分隔符方案下都会产生歧义（分隔符本身可以出现在字段内部）。
type idemIdentity struct {
	submitter string
	requestID string
}

type Store struct {
	dir string

	mu     sync.Mutex
	jobs   []*storedJob // 严格按作业号（即提交先后）排列
	byID   map[uint64]*storedJob
	idem   map[idemIdentity]uint64 // (提交人, 请求号) -> 作业号
	nextID uint64
	closed bool

	now func() time.Time

	runningID uint64
	waitCh    chan struct{}
	stopCh    chan struct{}
	stopping  atomic.Bool
	wg        sync.WaitGroup

	// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
	// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
	// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
	compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)

	// persistFault 仅用于包内确定性测试：若非 nil，每次 persist 都会先调用它，
	// 返回非 nil 即模拟该次记录保存失败（如同临时记录无法创建或原记录无法替换）。
	// 生产代码恒为 nil。钩子可按作业号与“待保存的当前状态”只让某一次写入失败
	// （例如仅让成功归档写入失败），而让其余记录照常落盘。
	persistFault func(j *storedJob) error
}

// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
//
// 恢复语义：
//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
//   - 目录内两份或更多记录文件顶层保存相同作业号（文件名不同、乃至内容
//     完全相同）时打开失败，返回非空错误且归档对象为 nil；错误说明重复的
//     作业号与冲突文件名。此时不启动任何计算，也不改写目录内任何原有
//     记录，调用方处理冲突后再次打开才按下列规则恢复；
//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
//   - 成功状态始终与完整归档同时可见。
func Open(dir string, opts ...Option) (*Store, error) {
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return nil, err
	}
	jobs, maxID, err := loadDir(dir)
	if err != nil {
		return nil, err
	}
	s := &Store{
		dir:    dir,
		jobs:   jobs,
		byID:   make(map[uint64]*storedJob),
		idem:   make(map[idemIdentity]uint64),
		nextID: maxID + 1,
		now:    wallClock{}.Now,
		waitCh: make(chan struct{}, 1),
		stopCh: make(chan struct{}),
	}
	for _, opt := range opts {
		opt(s)
	}
	for _, j := range jobs {
		s.byID[j.id] = j
		if j.requestID != "" {
			s.idem[idemIdentity{j.submitter, j.requestID}] = j.id
		}
	}
	// 重建失败/取消作业对排队下游的阻断。
	s.cascadeLocked()
	s.wg.Add(1)
	go s.worker()
	return s, nil
}

// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
// 排队作业原样保留在磁盘上，下次 [Open] 继续。
//
// 多次 Close（含并发调用）共同完成对同一个归档对象的一次关闭：每个调用都
// 等到 worker 退出、运行中作业的中断处理已经落盘后才成功返回。后发调用
// 不能只因为前一次调用已把关闭标记置位就提前返回——否则调用方可能据此立即
// 重新打开目录，而旧 worker 仍在补写运行作业的结果。归档完全关闭后的再次
// Close 立即成功返回；空闲归档（无运行中作业）也直接完成关闭。
func (s *Store) Close() error {
	s.mu.Lock()
	if s.closed {
		// 关闭可能正由另一次并发 Close 进行。wg 在 Open 时 +1、worker 退出
		// 时归零；Wait 允许被多个 goroutine 同时等待，所有调用都在同一次
		// 关闭真正完成（worker 已退出、再无计算与补写）时才返回。
		// 已完全关闭时计数早已归零，这里立即成功返回。
		s.mu.Unlock()
		s.wg.Wait()
		return nil
	}
	s.closed = true
	// 停止标记必须与 closed 在同一次持锁中生效：Submit 的拒绝、worker 的
	// “是否从队列启动新计算”与“是否把刚结束的计算确认为成功”都观察同一把
	// 锁。若先放开锁再置 stopping，worker 可能在这个窗口内通过循环开头的
	// 检查并启动排队作业，或把尚未确认保存的计算按成功落盘——调用方已经在
	// 被 ErrStoreClosed 拒绝，却仍能拿到关闭过程新产生的成功结果。
	if s.stopping.CompareAndSwap(false, true) {
		close(s.stopCh)
	}
	var running *storedJob
	if s.runningID != 0 {
		running = s.byID[s.runningID]
	}
	s.mu.Unlock()

	// 中止正在运行的计算。
	if running != nil {
		running.canceled.Store(true)
	}
	s.notify()
	s.wg.Wait()
	return nil
}

// Submit 接受一次作业提交。
//
// 空序列返回 [ErrEmptySequence]；依赖列表结构不合法（单依赖与列表同时启用、
// 含零或重复作业号）返回 [ErrInvalidDependency]——这些请求本身的格式错误先于
// 幂等判定拒绝，即使复用已接受的请求号也不例外。
//
// 非空请求号命中同一提交人的已接受请求时，幂等判定先于“引用的上游必须存在”
// 校验：内容（整数序列及次序、种子、有序依赖内容）完全一致时返回原作业的
// 当前详情且不返回错误，即使其直接上游记录在重开归档后已缺失、原作业已因此
// 被改判为失败；内容不一致返回 [ErrIdempotencyConflict]（同时返回原作业视图，
// 仍引用缺失上游时在原因中一并指出），原记录保持原样。重复提交不创建新作业、
// 不补建缺失上游、不重新排队失败作业、也不改写原始参数或失败记录。
//
// 未命中已接受请求的新请求（提交人不同、请求号不同或请求号为空）引用不存在
// 的依赖时返回 [ErrDependencyNotFound]；上述拒绝都不产生记录，也不占用请求号。
// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
func (s *Store) Submit(req SubmitRequest) (*Job, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed || s.stopping.Load() {
		return nil, ErrStoreClosed
	}
	if len(req.Values) == 0 {
		return nil, ErrEmptySequence
	}
	// 先校验与上游存在性无关的列表结构（单依赖与列表互斥、零与重复作业号），
	// 这类拒绝不依赖内存索引，对新请求与幂等重放一视同仁。
	if err := s.validateDependencyShapeLocked(&req); err != nil {
		return nil, err
	}
	deps := requestDeps(&req)
	if req.RequestID != "" {
		key := idemIdentity{req.Submitter, req.RequestID}
		if origID, ok := s.idem[key]; ok {
			orig := s.byID[origID]
			// 幂等重放先于“引用的上游必须存在”的校验：重新打开归档后原作业
			// 直接上游的记录可能已经缺失，原作业也因此被改判为失败并落盘。
			// 只要本次提交的整数序列及次序、种子与有序依赖内容和已接受请求
			// 完全一致（单依赖写法与只含同一作业号的列表等价），就返回原作业
			// 的当前详情——不重建缺失上游、不重新排队、不补算、不改写记录。
			if sameContent(orig, &req) {
				return s.viewLocked(orig), nil
			}
			return s.viewLocked(orig),
				fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d，且本次内容与原请求不一致%s，原记录保持原样",
					ErrIdempotencyConflict, req.Submitter, req.RequestID, origID,
					s.missingDependencyNoteLocked(deps))
		}
	}
	// 新请求（请求号为空，或该提交人首次使用此请求号）仍要求每个直接上游
	// 都存在；引用不存在上游的提交被拒绝，不产生记录，也不占用请求号。
	// 此检查必须位于幂等判定之后：上面的重放/冲突分支可能引用缺失的上游。
	if err := s.validateDependenciesExistLocked(deps); err != nil {
		return nil, err
	}

	now := s.now().UTC()
	j := &storedJob{
		id:           s.nextID,
		submitter:    req.Submitter,
		requestID:    req.RequestID,
		seed:         req.Seed,
		values:       append([]int64(nil), req.Values...),
		dependencies: append([]uint64(nil), deps...),
		queuedAt:     now,
		status:       StatusQueued,
	}
	// 先持久化，接受之后该提交即不可丢失。
	if err := s.persist(j); err != nil {
		return nil, err
	}
	s.nextID++
	s.jobs = append(s.jobs, j)
	s.byID[j.id] = j
	if req.RequestID != "" {
		s.idem[idemIdentity{req.Submitter, req.RequestID}] = j.id
	}
	// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
	s.cascadeLocked()
	s.notifyLocked()
	return s.viewLocked(j), nil
}

// requestDeps 规范化一次提交的直接上游作业号列表，与记录、归档共用 deps.go
// 中的同一换算：非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含
// 一个作业号的列表；两者皆无则为 nil。调用前须先经
// [Store.validateDependencyShapeLocked] 与（新请求路径上的）
// [Store.validateDependenciesExistLocked] 校验。
func requestDeps(req *SubmitRequest) []uint64 {
	return normalizeDependencies(req.HasDependency, req.DependencyID, req.Dependencies)
}

// validateDependencyShapeLocked 在持锁状态下校验提交依赖列表中与上游存在性
// 无关的结构问题：
//   - 单依赖方式与非空列表同时启用 → 拒绝；
//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）。
//
// 该校验先于幂等判定执行：空整数序列、依赖号为零、重复依赖与两种写法
// 同时启用都属于请求本身的格式错误，即使提交人+请求号与已接受请求相同
// 也仍返回原有的对应拒绝。
func (s *Store) validateDependencyShapeLocked(req *SubmitRequest) error {
	if req.HasDependency && len(req.Dependencies) > 0 {
		return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
	}
	deps := requestDeps(req)
	seen := make(map[uint64]struct{}, len(deps))
	for _, id := range deps {
		if id == 0 {
			return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
		}
		if _, dup := seen[id]; dup {
			return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
		}
		seen[id] = struct{}{}
	}
	return nil
}

// validateDependenciesExistLocked 校验规范化后的依赖列表只引用当前归档中
// 存在的作业。仅适用于幂等判定之后的新请求：已接受请求的重放（或内容
// 冲突）即使引用了重开后缺失的上游，也要返回原作业而不是被这里拒绝。
//
// 任一拒绝都不产生记录，也不占用幂等请求号。
func (s *Store) validateDependenciesExistLocked(deps []uint64) error {
	for _, id := range deps {
		if s.byID[id] == nil {
			return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
		}
	}
	return nil
}

// missingDependencyNoteLocked 在幂等冲突时补充说明：若本次（与原请求内容
// 不一致的）提交仍引用已经缺失的上游，明确指出缺失的作业号，使冲突原因
// 不会被误读成仅仅是上游不存在。
func (s *Store) missingDependencyNoteLocked(deps []uint64) string {
	for _, id := range deps {
		if s.byID[id] == nil {
			return fmt.Sprintf("；本次引用的直接上游作业 %d 记录已缺失", id)
		}
	}
	return ""
}

// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
func sameContent(j *storedJob, req *SubmitRequest) bool {
	if j.seed != req.Seed {
		return false
	}
	rd := requestDeps(req)
	if len(j.dependencies) != len(rd) {
		return false
	}
	for i := range j.dependencies {
		if j.dependencies[i] != rd[i] {
			return false
		}
	}
	if len(j.values) != len(req.Values) {
		return false
	}
	for i := range j.values {
		if j.values[i] != req.Values[i] {
			return false
		}
	}
	return true
}

// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
func (s *Store) Get(id uint64) (*Job, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	j := s.byID[id]
	if j == nil {
		return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
	}
	return s.viewLocked(j), nil
}

// Cancel 请求取消作业。
//
// 排队或运行中的作业都可以取消；取消以“取消状态已成功保存进归档记录”为生效
// 条件：只有原子替换原记录成功后，返回结果、可查询状态与磁盘记录才一致地呈现
// 为取消，该作业及依赖它的作业才不会再产生成功归档。若取消记录无法创建临时
// 文件或无法替换原记录，返回的是实际保存错误，作业保持原状——不新增完成时间、
// 不清空原有信息、不中止正在运行的计算、不级联标记下游，排队与调度规则不变；
// 写入条件恢复后对仍处于排队或运行状态的同一作业再次取消会重新尝试保存。
// 重复取消已取消的作业仍返回成功；对已成功或已失败的作业取消返回
// [ErrNotCancellable]，原结果保持不变（计算在两次取消请求之间完成时亦然）。
func (s *Store) Cancel(id uint64) (*Job, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		return nil, ErrStoreClosed
	}
	j := s.byID[id]
	if j == nil {
		return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
	}
	switch j.status {
	case StatusCanceled:
		return s.viewLocked(j), nil
	case StatusSucceeded, StatusFailed:
		return s.viewLocked(j),
			fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
	}

	// queued / running：先把取消终态写入原记录，确认原子替换成功后才让取消
	// 生效。持锁期间外界观察不到中间态；若创建临时记录或替换原记录失败，
	// 必须逐字段回滚，内存与磁盘都保持取消前的原状并返回实际保存错误，
	// 不能把这次取消当作已完成。
	now := s.now().UTC()
	prevStatus := j.status
	prevFinishedAt := j.finishedAt
	prevReason := j.failureReason
	prevBlocker := j.blockerID
	prevEffective := j.effectiveValues
	prevArchive := j.archive
	j.status = StatusCanceled
	j.failureReason = ""
	j.blockerID = 0
	if j.finishedAt.IsZero() {
		j.finishedAt = now
	}
	j.effectiveValues = nil
	j.archive = nil
	if err := s.persist(j); err != nil {
		j.status = prevStatus
		j.finishedAt = prevFinishedAt
		j.failureReason = prevReason
		j.blockerID = prevBlocker
		j.effectiveValues = prevEffective
		j.archive = prevArchive
		return nil, err
	}

	// 取消已确认保存：提交终态，让正在运行的计算尽快中止，并级联标记下游。
	j.canceled.Store(true)
	// 依赖它的等待者一并失败，且继续向更下游传播。
	s.cascadeLocked()
	s.notifyLocked()
	return s.viewLocked(j), nil
}

// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if !start.IsZero() && !end.IsZero() && start.After(end) {
		return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
			ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
	}
	out := make([]*Job, 0)
	for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
		if j.submitter != submitter {
			continue
		}
		if !start.IsZero() && j.queuedAt.Before(start) {
			continue
		}
		if !end.IsZero() && j.queuedAt.After(end) {
			continue
		}
		out = append(out, s.viewLocked(j))
	}
	return out, nil
}

// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
//
// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
// 扫描即可让阻断沿链条传播到最下游。选择直接阻断者、确定根因与构造失败
// 原因统一走 blocker.go 中的规则（与重开归档同一套）：作业有多个直接上游时
// 按保存的依赖顺序选取最靠前的已失败/取消者，根因沿该上游已有的阻断信息
// 保留；作业一旦失败，其原因不再被后来发生的上游状态变化改写。
func (s *Store) cascadeLocked() {
	for _, j := range s.jobs {
		if j.status != StatusQueued || len(j.dependencies) == 0 {
			continue
		}
		directID, direct, blocked := pickBlockingUpstream(j, s.byID, runtimeUpstreamBlocked)
		if !blocked {
			continue
		}
		root := blockerRoot(direct, directID)
		s.markFailedLocked(j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
	}
}

// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
// 该作业就被跳过，不挡住后面可运行的作业。
func (s *Store) pickRunnableLocked() *storedJob {
	for _, j := range s.jobs {
		if j.status != StatusQueued {
			continue
		}
		if len(j.dependencies) == 0 {
			return j
		}
		ready := true
		for _, id := range j.dependencies {
			dep := s.byID[id]
			if dep == nil || dep.status != StatusSucceeded {
				ready = false
				break
			}
		}
		if ready {
			return j
		}
	}
	return nil
}

// notifyLocked 在持锁状态下非阻塞唤醒 worker。
func (s *Store) notifyLocked() {
	select {
	case s.waitCh <- struct{}{}:
	default:
	}
}

// notify 在不持锁时唤醒 worker。
func (s *Store) notify() {
	s.mu.Lock()
	s.notifyLocked()
	s.mu.Unlock()
}

// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
func (s *Store) persistRetry(j *storedJob, attempts int) error {
	var err error
	for i := 0; i < attempts; i++ {
		if err = s.persist(j); err == nil {
			return nil
		}
	}
	return err
}

// worker 是本地唯一的计算执行体。
func (s *Store) worker() {
	defer s.wg.Done()
	for {
		s.mu.Lock()
		if s.stopping.Load() {
			s.mu.Unlock()
			return
		}
		j := s.pickRunnableLocked()
		if j == nil {
			ch := s.waitCh
			s.mu.Unlock()
			select {
			case <-ch:
			case <-s.stopCh:
			}
			continue
		}

		// 进入运行并原子持久化该状态。
		j.status = StatusRunning
		j.startedAt = s.now().UTC()
		// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
		inputs := append([]int64(nil), j.values...)
		for _, id := range j.dependencies {
			if dep := s.byID[id]; dep != nil && dep.archive != nil {
				inputs = append(inputs, dep.archive.Sum)
			}
		}
		seed := j.seed
		s.runningID = j.id
		if err := s.persistRetry(j, 3); err != nil {
			// 连运行状态都无法落盘：保守地失败，不进行计算。
			s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
			s.runningID = 0
			s.cascadeLocked()
			s.notifyLocked()
			s.mu.Unlock()
			continue
		}
		s.mu.Unlock()

		abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
		doCompute := s.compute
		if doCompute == nil {
			doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
				return computeResult(in, sd, c)
			}
		}
		sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)

		s.mu.Lock()
		s.runningID = 0
		switch {
		case j.status == StatusCanceled:
			// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
			j.archive = nil
			j.effectiveValues = nil
			_ = s.persistRetry(j, 3)
			s.cascadeLocked()
		case s.stopping.Load():
			s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
			s.cascadeLocked()
		case !ok:
			s.markFailedLocked(j, reason, 0)
			s.cascadeLocked()
		default:
			// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
			completed := s.now().UTC()
			a := newArchive(j, inputs, sum, sumSq, completed)
			j.effectiveValues = append([]int64(nil), inputs...)
			j.status = StatusSucceeded
			j.finishedAt = completed
			j.failureReason = ""
			j.blockerID = 0
			j.archive = a
			if err := s.persistRetry(j, 3); err != nil {
				// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
				j.archive = nil
				j.effectiveValues = nil
				s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
				// 归档写入失败与计算溢出等失败同等对待：立即沿依赖链阻断所有仍在
				// 排队等待它的作业，使等待者无需等到下一次提交/取消即进入失败终态。
				s.cascadeLocked()
			}
		}
		s.notifyLocked()
		s.mu.Unlock()
	}
}

// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
	j.status = StatusFailed
	j.failureReason = reason
	j.blockerID = blocker
	if j.finishedAt.IsZero() {
		j.finishedAt = s.now().UTC()
	}
	j.archive = nil
	j.effectiveValues = nil
	_ = s.persistRetry(j, 3)
}

// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
// 上游作业号只作记录，不参与任何摘要与校验值。
func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
	inDigest := inputsDigestHex(effective, j.seed)
	resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
	log := buildLog(effective, j.seed, sum, sumSquares)
	checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
	hasDependency, dependencyID := legacyDependencyFields(j.dependencies)
	return &Archive{
		JobID:           j.id,
		Submitter:       j.submitter,
		RequestID:       j.requestID,
		IdentityRaw:     rawIdentity(j.submitter, j.requestID),
		Seed:            j.seed,
		Values:          append([]int64(nil), j.values...),
		HasDependency:   hasDependency,
		DependencyID:    dependencyID,
		Dependencies:    append([]uint64(nil), j.dependencies...),
		EffectiveValues: append([]int64(nil), effective...),
		InputsDigest:    inDigest,
		Sum:             sum,
		SumOfSquares:    sumSquares,
		ResultDigest:    resDigest,
		Log:             log,
		Checksum:        checksum,
		CompletedAt:     completedAt,
	}
}

// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
func (s *Store) viewLocked(j *storedJob) *Job {
	v := &Job{
		ID:              j.id,
		Submitter:       j.submitter,
		RequestID:       j.requestID,
		Seed:            j.seed,
		Values:          append([]int64(nil), j.values...),
		Dependencies:    append([]uint64(nil), j.dependencies...),
		QueuedAt:        j.queuedAt,
		StartedAt:       j.startedAt,
		FinishedAt:      j.finishedAt,
		Status:          j.status,
		FailureReason:   j.failureReason,
		BlockerID:       j.blockerID,
		EffectiveValues: append([]int64(nil), j.effectiveValues...),
	}
	v.HasDependency, v.DependencyID = legacyDependencyFields(j.dependencies)
	if j.status == StatusQueued {
		v.WaitReason = WaitSlot
		// 列出尚未成功归档的直接上游，保持提交时的顺序。
		for _, id := range j.dependencies {
			if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
				v.PendingDependencies = append(v.PendingDependencies, id)
			}
		}
		if len(v.PendingDependencies) > 0 {
			v.WaitReason = WaitDependency
		}
	}
	if j.archive != nil {
		a := *j.archive
		a.Values = append([]int64(nil), j.archive.Values...)
		a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
		a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
		if j.archive.IdentityRaw != nil {
			raw := *j.archive.IdentityRaw
			a.IdentityRaw = &raw
		}
		v.Archive = &a
	}
	return v
}

// Dir 返回归档目录路径。
func (s *Store) Dir() string { return s.dir }

package numeric

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync/atomic"
	"time"
	"unicode/utf8"
)

// rawBase64Prefix 标记 _raw 字段中的值是原始字节的 base64 编码。
// ':' 不在 base64 字母表内，普通文本（即使本身像 base64，如 "abcd"）
// 不会以该前缀开头；而 _raw 字段由本版本写入，旧归档不含此字段，
// 因此标记无歧义。
const rawBase64Prefix = "base64:"

// unmarshalRaw 恢复 rawIdentity 写出的字段；带 base64 前缀的兜底值解码回
// 原始字节，普通 JSON 字符串原样返回。
func unmarshalRaw(s string) (string, error) {
	if strings.HasPrefix(s, rawBase64Prefix) {
		b, err := base64.StdEncoding.DecodeString(s[len(rawBase64Prefix):])
		if err != nil {
			return "", fmt.Errorf("numeric: 标识原始字节解码失败: %w", err)
		}
		return string(b), nil
	}
	return s, nil
}

// identityRaw 携带提交人、请求号的完整字节兜底表示。只有当对应字段含
// 非法 UTF-8 字节时相应成员才非空；普通文本记录不写这两个字段，
// 保持旧格式归档可直接打开。
type identityRaw struct {
	Submitter string `json:"submitter_raw,omitempty"`
	RequestID string `json:"request_id_raw,omitempty"`
}

// rawIdentity 在标识含非法 UTF-8 字节时构造完整字节兜底字段；
// 两个标识都是合法 UTF-8 时返回 nil，记录与旧格式完全一致。
func rawIdentity(submitter, requestID string) *identityRaw {
	if utf8.ValidString(submitter) && utf8.ValidString(requestID) {
		return nil
	}
	raw := &identityRaw{}
	if !utf8.ValidString(submitter) {
		raw.Submitter = rawBase64Prefix + base64.StdEncoding.EncodeToString([]byte(submitter))
	}
	if !utf8.ValidString(requestID) {
		raw.RequestID = rawBase64Prefix + base64.StdEncoding.EncodeToString([]byte(requestID))
	}
	return raw
}

// resolveIdentity 恢复提交人、请求号：_raw 兜底字段存在且非空时以其
// 解码出的完整字节为准，否则使用 JSON 字符串字段（旧归档与普通文本）。
func resolveIdentity(plainSub, plainReq string, raw *identityRaw) (string, string, error) {
	var err error
	sub, req := plainSub, plainReq
	if raw != nil {
		if raw.Submitter != "" {
			if sub, err = unmarshalRaw(raw.Submitter); err != nil {
				return "", "", err
			}
		}
		if raw.RequestID != "" {
			if req, err = unmarshalRaw(raw.RequestID); err != nil {
				return "", "", err
			}
		}
	}
	return sub, req, nil
}

// recordVersion 是落盘记录格式的版本标记。
const recordVersion = "numeric-job-v1"

// storedJob 是作业在内存中的完整状态，所有字段均由 Store.mu 保护。
type storedJob struct {
	id           uint64
	submitter    string
	requestID    string
	seed         int64
	values       []int64
	dependencies []uint64 // 有序直接上游作业号；空表示无依赖

	queuedAt   time.Time
	startedAt  time.Time
	finishedAt time.Time

	status        Status
	failureReason string
	blockerID     uint64

	// 成功后保存的有效输入与归档（与 succeeded 状态同一次原子写入）。
	effectiveValues []int64
	archive         *Archive

	// canceled 仅存于内存：运行中的作业收到取消/关闭请求后置位，
	// 计算循环据此尽快中止；终态不会依赖它落盘（终态本身会持久化）。
	canceled atomic.Bool
}

// jobRecord 是 storedJob 的落盘 JSON 表示。成功状态与归档在同一记录内，
// 一次 temp-file + rename 原子写入，因此对外不会出现“成功却没有结果”。
type jobRecord struct {
	Version string `json:"version"`

	ID        uint64 `json:"id"`
	Submitter string `json:"submitter"`
	RequestID string `json:"request_id"`
	// IdentityRaw 仅在提交人或请求号含非法 UTF-8 字节时出现，按完整字节
	// 保真恢复标识；合法 UTF-8（含 U+0000）时缺省，记录与旧格式一致。
	IdentityRaw   *identityRaw `json:"identity_raw,omitempty"`
	Seed          int64        `json:"seed"`
	Values        []int64      `json:"values"`
	HasDependency bool         `json:"has_dependency"`
	DependencyID  uint64       `json:"dependency_id"`
	// Dependencies 为有序直接上游作业号；旧格式记录无此字段，
	// 恢复时由 HasDependency/DependencyID 推导。
	Dependencies []uint64 `json:"dependencies,omitempty"`

	QueuedAt   time.Time `json:"queued_at"`
	StartedAt  time.Time `json:"started_at,omitempty"`
	FinishedAt time.Time `json:"finished_at,omitempty"`

	Status        Status `json:"status"`
	FailureReason string `json:"failure_reason,omitempty"`
	BlockerID     uint64 `json:"blocker_id,omitempty"`

	EffectiveValues []int64  `json:"effective_values,omitempty"`
	Archive         *Archive `json:"archive,omitempty"`
}

func jobFileName(id uint64) string {
	return fmt.Sprintf("job-%020d.json", id)
}

func (s *Store) jobPath(j *storedJob) string {
	return filepath.Join(s.dir, jobFileName(j.id))
}

func encodeRecord(j *storedJob) ([]byte, error) {
	hasDependency, dependencyID := legacyDependencyFields(j.dependencies)
	r := jobRecord{
		Version: recordVersion,

		ID:            j.id,
		Submitter:     j.submitter,
		RequestID:     j.requestID,
		IdentityRaw:   rawIdentity(j.submitter, j.requestID),
		Seed:          j.seed,
		Values:        append([]int64(nil), j.values...),
		HasDependency: hasDependency,
		DependencyID:  dependencyID,
		Dependencies:  append([]uint64(nil), j.dependencies...),

		QueuedAt:      j.queuedAt,
		StartedAt:     j.startedAt,
		FinishedAt:    j.finishedAt,
		Status:        j.status,
		FailureReason: j.failureReason,
		BlockerID:     j.blockerID,

		EffectiveValues: append([]int64(nil), j.effectiveValues...),
		Archive:         j.archive,
	}
	return json.MarshalIndent(&r, "", "  ")
}

// persist 在已持锁的情况下原子写一条作业记录。
func (s *Store) persist(j *storedJob) error {
	// 测试用故障注入点（生产代码中 persistFault 恒为 nil）。
	if s.persistFault != nil {
		if err := s.persistFault(j); err != nil {
			return err
		}
	}
	data, err := encodeRecord(j)
	if err != nil {
		return err
	}
	return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
}

// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
	tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	cleanup := true
	defer func() {
		if cleanup {
			_ = os.Remove(tmpName)
		}
	}()

	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmpName, perm); err != nil {
		return err
	}
	if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
		return err
	}
	cleanup = false
	syncDir(dir)
	return nil
}

// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
func syncDir(dir string) {
	if d, err := os.Open(dir); err == nil {
		_ = d.Sync()
		_ = d.Close()
	}
}

// loadDir 扫描目录中的全部作业记录并重建内存索引。
//
// 恢复规则：
//   - 两份或更多记录文件顶层保存相同作业号时（即使文件名不同或内容完全
//     相同），本次打开直接失败并返回说明该作业号与冲突文件名的非空错误：
//     一个稳定作业号只能对应一份已保存作业。该检查在所有记录都可正常解析、
//     版本及状态合法之后、任何恢复改写之前完成，因此冲突时不会启动任何
//     计算，也不会改判或补写目录内的任何原有记录（中断的运行记录、待复查
//     的成功记录、排队记录等全部保持原样）；不按时间、状态、排列或完整度
//     挑选一份，也不自动换号、合并或删除，调用方处理冲突后再次打开才按
//     既有规则恢复；
//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
//   - 成功记录缺少归档、校验值对不上，依赖列表重复引用同一直接上游作业号，
//     或直接上游作业号不小于本作业号（引用自己或后来作业，违反提交时的
//     先后关系规则），实际输入与原始参数或直接依赖数量不对应，或归档数值
//     结果与有效输入按计算规则应得的结果不符时，fail-closed 地标记为失败，
//     维持“成功必有完整归档”的不变量；
//   - 有依赖的成功记录还要求每个直接上游都存在、恢复后仍是带完整归档的
//     成功状态，且实际输入的追加部分逐项等于这些上游按保存的依赖顺序
//     排列的总和；上游不可用的同样改判为失败，其失败原因指出直接上游、
//     BlockerID 沿链条保留最初的根因（与运行中依赖失败同一规则）；
//     仅追加输入对不上而上游全部有效的属于本作业自身归档有误，BlockerID
//     保持 0。排队记录的依赖列表重复引用同一作业号，或引用作业号不小于
//     自己的作业（自己/后来作业），同样在恢复时直接判失败（BlockerID 为
//     0），不再等待或开始计算；排队记录的原始整数序列为空（缺省、null 或
//     空数组）也直接判失败（BlockerID 为 0）——提交时即拒绝空序列，恢复时
//     不能凭已有实际输入或成功上游的总和补出原始参数后继续计算。仍在排队
//     的其他作业在同一趟升序扫描中按既有依赖规则级联失败。
func loadDir(dir string) ([]*storedJob, uint64, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, 0, err
	}
	// 第一阶段：只读解析全部记录文件，不进行任何恢复改写。这样重复作业号
	// 检查可以在第一条记录被改判失败或补写结果之前作出判断：一个稳定作业号
	// 只能对应一份已保存作业，两份顶层作业号相同的记录（文件名不同、内容
	// 完全相同也不例外）必须让本次打开整体失败，而不是按文件排列、时间或
	// 状态挑一份继续，也不能先按正常恢复规则把其他作业改判失败/补写结果再
	// 报错——冲突时本次打开不启动任何计算，也不改写目录内任何原有记录。
	type parsedRecord struct {
		name string
		job  *storedJob
	}
	var parsed []parsedRecord
	var maxID uint64
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() {
			continue
		}
		// 清理上一进程崩溃时可能残留的原子写临时文件。
		if strings.HasPrefix(name, ".tmp-") {
			_ = os.Remove(filepath.Join(dir, name))
			continue
		}
		if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
			continue
		}
		j, err := parseJobRecord(dir, name)
		if err != nil {
			return nil, 0, err
		}
		parsed = append(parsed, parsedRecord{name: name, job: j})
		if j.id > maxID {
			maxID = j.id
		}
	}

	// 重复作业号检查：所有记录都可正常解析、版本与状态合法之后，在任何恢复
	// 改写与第二趟依赖失效处理之前执行。检查按目录列举顺序进行，但结果不
	// 依赖文件排列——只要同一作业号出现至少两次即构成冲突；错误中给出该
	// 作业号以及全部冲突记录的文件名（至少两份），便于调用方定位。不按
	// 提交时间、状态、排列或哪份带完整结果挑选，也不自动换号、合并参数或
	// 删除冲突文件；调用方处理完冲突后再次打开才按既有规则恢复。
	seen := make(map[uint64]*parsedRecord, len(parsed))
	for i := range parsed {
		rec := &parsed[i]
		if prev, dup := seen[rec.job.id]; dup {
			return nil, 0, duplicateJobIDError(rec.job.id, prev.name, rec.name)
		}
		seen[rec.job.id] = rec
	}

	jobs := make([]*storedJob, 0, len(parsed))
	for _, rec := range parsed {
		jobs = append(jobs, rec.job)
	}

	// 第二阶段：至此目录中每个作业号只对应一份记录，下面的既有恢复规则
	// （中断改判、成功归档复核、排队记录自身有误与依赖失效级联）才允许
	// 改写记录。第一趟状态修正只依赖单条记录自身，直接逐个执行即可。
	for _, j := range jobs {
		if j.status == StatusRunning {
			failRestoredJob(dir, j, "计算被中断：归档上次关闭时作业仍在运行", 0)
		}
		if j.status == StatusSucceeded {
			// 除完整性外，还必须满足三条独立的对应/复算规则：
			//  0. 依赖列表自身合法，按以下顺序检查：
			//     a. 同一直接上游作业号不能出现两次（相邻或隔着其他上游都算）。
			//        这与提交时 validateDependencyShapeLocked 的唯一性要求一致；
			//        旧版本或被改动的记录可能保存了重复引用，此时即使追加值、
			//        总和、平方和、摘要、日志与校验值全部自洽，也不能当作合法
			//        成功归档（重复引用会把同一上游总和追加两次）。
			//     b. 每个直接上游作业号都必须严格小于本作业号。正常提交只能引用
			//        已经存在的作业，作业号又按接受先后递增，所以引用自己或引用
			//        后来作业都不可能通过提交校验；旧版本或被改动的记录可能保存
			//        这种依赖，即使被引用作业确实存在且成功、本作业的追加值、总和、
			//        平方和、摘要、日志与校验值全部自洽，也不能接受。已因重复
			//        依赖判失败的记录保留重复失败说明，不再改写。
			//     两项都属于本作业记录自身有误，在任何上游可用性核对之前判定，
			//     BlockerID 为 0，不把被引用的有效上游判成失败。
			//  1. 实际输入与原始参数、直接依赖数量逐项对应——原始序列非空且
			//     按原次序完整出现在实际输入开头，总长度恰为原始长度加上直接
			//     依赖数；摘要、日志、校验值只与“实际输入”绑定，换成另一份
			//     序列（如 [-3,2] 冒充 [2,-3]）仍能全套自洽，只有按位置比对
			//     原始参数与依赖数量才能识别。
			//  2. 归档中的数值结果必须与实际输入按既有计算规则应得的结果一致：
			//     日志、摘要与校验值都可能与错误数字自洽，只有按保存的实际
			//     输入复算才能识别。
			// 任一不符合都按损坏归档处理。第四条规则——追加部分逐项等于各
			// 直接上游恢复后的总和——需要全部记录恢复完毕才能核对，
			// 在排序后的第二趟扫描中执行。
			var invalidReason string
			if dupID, dup := duplicateDependency(j); dup {
				invalidReason = duplicateDependencyReason(dupID)
			} else if badID, bad := firstIllegalOrderingDependency(j); bad {
				invalidReason = illegalOrderingDependencyReason(badID, j.id)
			} else if !archiveIntact(j) {
				invalidReason = "归档不完整或校验值不一致，成功结果不可用"
			} else if !effectiveInputsCorrespond(j) {
				invalidReason = "实际输入与原始参数或依赖数量不符，成功结果不可用"
			} else if !archiveResultsValid(j) {
				invalidReason = "归档数值结果与有效输入按计算规则应得的结果不符，成功结果不可用"
			}
			if invalidReason != "" {
				// 归档自身校验不通过：属于本作业自身失败，不携带阻断根因。
				failRestoredJob(dir, j, invalidReason, 0)
			}
		}
	}
	// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
	// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
	// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
	// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
	// 依赖链在单趟级联扫描中漏掉失败传播）。
	sort.Slice(jobs, func(a, b int) bool {
		return jobs[a].id < jobs[b].id
	})
	// 第二趟：按作业号升序单趟处理依赖失效。直接上游在提交时必须已存在，
	// 上游作业号必然更小，因此每个作业被处理时其全部直接上游都已是本次恢复
	// 确定的最终状态——上游被改判失败时携带的根因作业号可直接沿链条继承，
	// 不会在每经过一个已归档的中间作业时重新起算。
	//
	// 两类作业遵守同一项归因规则（与正常运行中的依赖失败一致）：失败原因
	// 指出当前作业的直接上游，BlockerID 沿链条保留最初使结果不可用的根因；
	// 只有本作业自身归档有误（上游全部有效、仅保存的追加输入不符）时
	// BlockerID 才保持 0。
	//   - 带依赖的成功记录：追加部分与上游恢复后的结果逐项核对；
	//   - 排队记录：先检查记录自身是否合法——依赖列表重复引用同一作业号、
	//     引用作业号不小于自己的作业（自己或后来作业），或原始整数序列为空，
	//     都属本作业自身有误，BlockerID 为 0，立即失败（重复检查最前，空序列
	//     检查最后）；再按保存的依赖顺序选取最靠前的不可用上游（已失败/取消，
	//     或记录缺失），立即级联失败，不再等待。
	//
	// 依赖列表自身不合法属于记录自身问题，先于一切上游可用性判断：即使被引用
	// 的上游仍在排队或确实存在且成功，不合法记录也要立即失败；而等待该记录
	// 结果的下游则按既有规则把它当作失败上游级联，根因就是这份记录自身。
	byID := make(map[uint64]*storedJob, len(jobs))
	for _, j := range jobs {
		byID[j.id] = j
	}
	for _, j := range jobs {
		if j.status == StatusQueued {
			// 排队记录自身有误的三项检查先于一切上游可用性判断，对有无依赖的
			// 记录同样适用（无依赖时前两项自然不命中）：
			//  1. 依赖列表重复引用同一作业号：不能开始计算，也不能把同一上游
			//     总和追加两次后继续。BlockerID 保持 0，不把被重复引用且原本
			//     有效的上游改成失败。
			//  2. 依赖先后关系不合法：直接上游作业号必须严格小于本作业号，
			//     引用自己或后来作业即使被引用者存在且成功也不能接受，不能开始
			//     计算或继续等待。排在重复检查之后，已因重复依赖判失败的记录
			//     保留现有说明。
			//  3. 原始整数序列为空（缺省、null 或空数组）：提交时即拒绝空序列，
			//     恢复时遵守同一项输入要求——不能开始运行，也不能凭已有实际输入
			//     或成功上游的总和补出原始参数。BlockerID 保持 0。空序列指没有
			//     任何原始整数；[0]、[0,0] 等非空序列仍是合法输入，不按总和
			//     是否为 0 判断。
			if dupID, dup := duplicateDependency(j); dup {
				failRestoredJob(dir, j, duplicateDependencyReason(dupID), 0)
				continue
			}
			if badID, bad := firstIllegalOrderingDependency(j); bad {
				failRestoredJob(dir, j, illegalOrderingDependencyReason(badID, j.id), 0)
				continue
			}
			if len(j.values) == 0 {
				failRestoredJob(dir, j, emptyOriginalValuesReason(), 0)
				continue
			}
		}
		if len(j.dependencies) == 0 {
			continue
		}
		switch j.status {
		case StatusSucceeded:
			// 第一趟：按保存的依赖顺序找最靠前的不可用上游（记录缺失或恢复后
			// 未保持带完整归档的成功状态）。
			directID, dep, unavailable := pickBlockingUpstream(j, byID, restoredArchiveUpstreamBlocked)
			if unavailable {
				// 因直接上游结果失效而失败：根因沿该上游已有的阻断信息保留，
				// 直接上游记录缺失时以缺失的作业号本身作为根因。
				root := blockerRoot(dep, directID)
				failRestoredJob(dir, j, blockedFailureReason(restoredArchiveHead(directID), dep, directID, root), root)
				continue
			}
			// 第二趟：直接上游全部存在且有效，只是本作业保存的追加输入与上游
			// 总和按位置对不上——属于本作业自身归档有误，不把有效上游判成
			// 失败或归因给它，BlockerID 保持 0。
			if _, detail, mismatch := firstAppendedMismatch(j, byID); mismatch {
				failRestoredJob(dir, j, detail, 0)
			}
		case StatusQueued:
			// 记录自身的三项检查已在上面完成；这里按保存的依赖顺序选取最靠前
			// 的不可用上游，其他上游作业号更小或失败原因不同都不能改变这个选择。
			directID, direct, blocked := pickBlockingUpstream(j, byID, restoredQueuedUpstreamBlocked)
			if !blocked {
				continue // 上游仍在排队等情况：继续等待，不挡住其他作业。
			}
			root := blockerRoot(direct, directID)
			if direct == nil {
				// 直接上游的记录在归档目录中缺失，其结果不可能再变为可用：
				// 以缺失的作业号作为根因，并明确说明结果无法使用。
				failRestoredJob(dir, j, blockedFailureReason(restoredMissingHead(directID), nil, directID, root), root)
				continue
			}
			failRestoredJob(dir, j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
		}
	}
	return jobs, maxID, nil
}

// parseJobRecord 只读解析单个作业记录文件并构造内存中的恢复作业，不执行任何
// 依赖其他记录的核对，也绝不写目录。原有的打开错误在此阶段继续有效并保持
// 原有信息：JSON 无法解析（记录损坏）、版本不受支持、标识兜底字节损坏或
// 状态非法都直接返回非空错误——这类记录不会因为同目录里恰好存在重复作业号
// 而改变错误类型。
//
// running 改判与成功归档复核等会改写记录的恢复步骤不在此处进行：调用方先
// 解析完全部记录并确认作业号无重复之后，才允许进入恢复改写阶段。
func parseJobRecord(dir, name string) (*storedJob, error) {
	path := filepath.Join(dir, name)
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var r jobRecord
	if err := json.Unmarshal(data, &r); err != nil {
		return nil, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
	}
	if r.Version != recordVersion {
		return nil, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
	}
	// 提交人、请求号按完整字节恢复：含非法 UTF-8 字节时以
	// identity_raw 兜底字段为准，普通文本（含 U+0000）与旧归档原样使用。
	submitter, requestID, err := resolveIdentity(r.Submitter, r.RequestID, r.IdentityRaw)
	if err != nil {
		return nil, fmt.Errorf("numeric: 记录 %s 标识损坏: %w", name, err)
	}
	// 成功归档内嵌同一份标识，同样按其自身兜底字段恢复，保证顶层记录
	// 与归档中的参数逐字节一致。
	if r.Archive != nil {
		aSub, aReq, aErr := resolveIdentity(r.Archive.Submitter, r.Archive.RequestID, r.Archive.IdentityRaw)
		if aErr != nil {
			return nil, fmt.Errorf("numeric: 记录 %s 归档标识损坏: %w", name, aErr)
		}
		r.Archive.Submitter = aSub
		r.Archive.RequestID = aReq
	}
	switch r.Status {
	case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
	default:
		return nil, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
	}
	// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
	// 恢复为只含一个作业号的列表（语义与提交时一致）。两类字段同时
	// 出现时以非空列表为实际依赖，与提交、归档核对共用同一换算。
	deps := normalizeDependencies(r.HasDependency, r.DependencyID, r.Dependencies)
	return &storedJob{
		id:           r.ID,
		submitter:    submitter,
		requestID:    requestID,
		seed:         r.Seed,
		values:       append([]int64(nil), r.Values...),
		dependencies: deps,

		queuedAt:   r.QueuedAt,
		startedAt:  r.StartedAt,
		finishedAt: r.FinishedAt,

		status:        r.Status,
		failureReason: r.FailureReason,
		blockerID:     r.BlockerID,

		effectiveValues: append([]int64(nil), r.EffectiveValues...),
		archive:         r.Archive,
	}, nil
}

// duplicateJobIDError 构造重复作业号冲突的打开错误：明确说明存在重复作业号，
// 包含该作业号以及至少两份冲突记录的文件名。更多冲突文件不逐个展开，但
// first 与 second 已足以让调用方定位冲突；列出哪些文件不取决于提交时间、
// 状态是否成功、文件排列或哪份带有完整结果。
func duplicateJobIDError(id uint64, first, second string) error {
	return fmt.Errorf("numeric: 归档目录存在重复作业号 %d：一个稳定作业号只能对应一份已保存作业，"+
		"但记录文件 %s 与 %s 顶层保存了相同作业号；拒绝打开且不改动任何记录，请处理冲突文件后重试",
		id, first, second)
}

// failRestoredJob 收拢重新打开归档时把恢复出的作业改判为失败的统一处理，
// 供六类恢复失败共用（调用顺序即各类判定的既有先后）：
//   - 上次关闭时仍在运行的作业：计算被中断（第一趟记录扫描）；
//   - 原标为成功、但归档完整性、依赖列表唯一性或先后关系、实际输入对应
//     关系或数值结果不符规则的作业：本作业自身归档校验失败（第一趟记录
//     扫描，BlockerID 恒 0；唯一性检查先于先后关系检查）；
//   - 排队记录的依赖列表重复引用同一作业号：本作业记录自身有误（第二趟升序
//     扫描，BlockerID 恒 0，先于上游可用性判断）；
//   - 排队记录引用作业号不小于自己的作业（自己/后来作业）：本作业记录自身
//     有误（第二趟升序扫描，BlockerID 恒 0，在重复检查之后、空序列检查与
//     上游可用性判断之前）；
//   - 排队记录的原始整数序列为空（缺省、null 或空数组）：本作业记录自身
//     有误（第二趟升序扫描，BlockerID 恒 0，在依赖列表自身合法性检查之后、
//     上游可用性判断之前）；
//   - 被不可用直接上游阻断的作业：成功记录复核与排队记录复查（第二趟升序扫描），
//     BlockerID 由调用方按 blocker.go 的归因规则给出。
//
// 处理内容与各处原先内联的步骤完全一致：置失败状态、失败原因与阻断根因；
// 已经有完成时间的记录保留该时间，只有没有完成时间的才补上当前时间；
// 清除成功归档与实际参与计算的输入，使按作业号读取与按提交人列举都不再返回
// 成功归档或实际输入；作业号、提交人、请求号、原始整数次序、种子、依赖次序
// 与已有开始时间均不在此改动。归档可正常写入时，变化经同一条记录的一次
// 原子替换写回磁盘，而不只停留在内存查询结果中；写入失败维持既有尽力而为
// 语义（不因恢复阶段的一次落盘失败让整个归档无法打开）。
func failRestoredJob(dir string, j *storedJob, reason string, blocker uint64) {
	j.status = StatusFailed
	j.failureReason = reason
	j.blockerID = blocker
	if j.finishedAt.IsZero() {
		j.finishedAt = time.Now().UTC()
	}
	j.effectiveValues = nil
	j.archive = nil
	if data, err := encodeRecord(j); err == nil {
		_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
	}
}

// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
func archiveIntact(j *storedJob) bool {
	a := j.archive
	if a == nil {
		return false
	}
	// 归档中的原始参数必须与记录顶层字段一致。
	wantHasDependency, wantDependencyID := legacyDependencyFields(j.dependencies)
	if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
		a.Seed != j.seed || a.HasDependency != wantHasDependency {
		return false
	}
	if a.HasDependency && a.DependencyID != wantDependencyID {
		return false
	}
	// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
	// 由单依赖字段推导后再比较，与记录恢复、提交内容比较共用同一换算。
	aDeps := normalizeDependencies(a.HasDependency, a.DependencyID, a.Dependencies)
	if len(aDeps) != len(j.dependencies) {
		return false
	}
	for i := range j.dependencies {
		if aDeps[i] != j.dependencies[i] {
			return false
		}
	}
	if len(a.Values) != len(j.values) {
		return false
	}
	for i := range j.values {
		if a.Values[i] != j.values[i] {
			return false
		}
	}
	if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
		return false
	}
	for i := range j.effectiveValues {
		if j.effectiveValues[i] != a.EffectiveValues[i] {
			return false
		}
	}
	if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
		return false
	}
	if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
		return false
	}
	if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
		return false
	}
	if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
		return false
	}
	return true
}

// archiveResultsValid 按既有计算规则对归档保存的实际输入（effectiveValues，
// 已含按顺序追加的上游总和，不再追加）复算总和与平方和，归档中的数值结果
// 必须与复算结果完全一致。完整性检查只验证日志、摘要与校验值和所写数字
// 自洽，无法识别“数字本身写错但全套字段一致”的记录，因此这里以计算规则
// 为准。实际输入按规则会造成 int64 溢出时 ok 为 false，任何数值结果
// （包括回绕后的值）都不能作为有效成功结果保留。
//
// 调用前须已通过 archiveIntact（保证 archive 非空且有效输入非空）。
func archiveResultsValid(j *storedJob) bool {
	a := j.archive
	sum, sumSquares, _, ok := computeResult(j.effectiveValues, j.seed, nil)
	if !ok {
		return false
	}
	return a.Sum == sum && a.SumOfSquares == sumSquares
}

// effectiveInputsCorrespond 校验成功记录中实际参与计算的输入与原始提交
// 参数、直接依赖数量之间的对应关系：
//   - 原始序列必须非空；
//   - 原始序列逐项、按原次序完整出现在实际输入的开头——负数、零与重复
//     整数一律按位置判断，不比较总和或平方和，也不忽略次序；
//   - 实际输入总长度必须恰好等于原始序列长度加直接依赖数量。无依赖时两份
//     序列必须完全相同；有单个或多个依赖时，原始部分之后只能保留每个直接
//     上游各占一个位置的追加部分，不能借依赖之名替换、截短原始部分，也不
//     能多出未记录的输入。
//
// 该规则防止把另一份输入的自洽结果挂在原始参数下：例如原始参数为 [2,-3]
// 而实际输入被换成 [-3,2] 时，总和与平方和不变，摘要、日志与校验值又只
// 绑定实际输入，全套字段仍会自洽，只有按位置比对原始参数并核对追加数量
// 才能识别。旧的单依赖记录恢复后依赖列表恰含一个作业号，按同一含义判断。
//
// 调用前须已通过 archiveIntact（保证 archive 非空、实际输入非空且归档内
// 副本与顶层一致）。
func effectiveInputsCorrespond(j *storedJob) bool {
	n := len(j.values)
	if n == 0 {
		return false
	}
	if len(j.effectiveValues) != n+len(j.dependencies) {
		return false
	}
	for i := 0; i < n; i++ {
		if j.effectiveValues[i] != j.values[i] {
			return false
		}
	}
	return true
}

// Package numeric 实现本地数值作业的提交、调度、取消与结果归档。
//
// 作业对有符号 64 位整数序列计算总和 (sum) 与平方和 (sum of squares)。
// 本地一次只运行一个作业，其余可运行作业严格按提交先后依次执行；
// 正在等待依赖结果的作业不会挡住后面可运行的作业。
//
// 所有已确认的状态（提交、取消、成功/失败结果）都持久化到目录中，
// 重新 [Store.Open] 同一目录后状态不丢失，幂等请求号继续生效，
// 上次关闭时仍在运行的作业会被标记为失败并阻止其下游继续计算。
package numeric

import (
	"errors"
	"time"
)

// Status 表示作业的状态。
type Status string

const (
	// StatusQueued 表示作业已接受，正在排队（等待计算位置或依赖结果）。
	StatusQueued Status = "queued"
	// StatusRunning 表示作业正在本地计算。
	StatusRunning Status = "running"
	// StatusSucceeded 表示计算成功，且结果已与成功状态一同归档落盘。
	StatusSucceeded Status = "succeeded"
	// StatusFailed 表示作业失败（输入溢出、依赖未通过、重启被中断等）。
	StatusFailed Status = "failed"
	// StatusCanceled 表示作业被提交人取消。
	StatusCanceled Status = "canceled"
)

// WaitReason 描述排队作业当前在等待什么。
type WaitReason string

const (
	// WaitSlot 表示依赖（若有）已产出可使用的结果，作业在等待本地唯一的计算位置。
	WaitSlot WaitReason = "waiting for computation slot"
	// WaitDependency 表示作业在等待其依赖的作业产出结果。
	WaitDependency WaitReason = "waiting for dependency result"
)

// 包级哨兵错误，调用方使用 errors.Is 判断。
var (
	// ErrEmptySequence 表示提交的整数序列为空，该提交被拒绝且不产生记录。
	ErrEmptySequence = errors.New("numeric: 整数序列为空，拒绝提交")
	// ErrNotFound 表示按作业号查不到作业。
	ErrNotFound = errors.New("numeric: 作业不存在")
	// ErrDependencyNotFound 表示提交引用了不存在的依赖作业，提交被拒绝且不产生记录。
	ErrDependencyNotFound = errors.New("numeric: 依赖作业不存在，拒绝提交")
	// ErrInvalidDependency 表示提交的依赖列表不合法：含有零或重复作业号，
	// 或与单依赖方式同时填写了非空列表；该提交被拒绝且不产生记录。
	ErrInvalidDependency = errors.New("numeric: 依赖列表不合法，拒绝提交")
	// ErrIdempotencyConflict 表示同一提交人使用了已存在的幂等请求号，
	// 但提交内容（整数次序、种子或依赖）与原提交不一致，保留原记录。
	ErrIdempotencyConflict = errors.New("numeric: 幂等请求号冲突，提交内容与原提交不一致")
	// ErrNotCancellable 表示作业已处于成功或失败终态，不能取消，原结果保持不变。
	ErrNotCancellable = errors.New("numeric: 作业已结束，不能取消")
	// ErrInvalidTimeRange 表示列举查询的起始时间晚于结束时间。
	ErrInvalidTimeRange = errors.New("numeric: 查询时间范围无效，起始时间晚于结束时间")
	// ErrStoreClosed 表示归档已关闭，不再接受操作。
	ErrStoreClosed = errors.New("numeric: 归档已关闭")
)

// SubmitRequest 是一次作业提交的原始参数。
type SubmitRequest struct {
	// Submitter 为提交人标识，与 RequestID 共同构成幂等键。
	Submitter string
	// RequestID 为幂等请求号，在同一提交人内有效。
	RequestID string
	// Values 为有符号 64 位整数序列，次序属于提交内容的一部分；为空则拒绝提交。
	Values []int64
	// Seed 为种子，属于提交内容的一部分，并参与结果摘要与校验值计算。
	Seed int64
	// HasDependency 为 true 时 DependencyID 指定本作业依赖的已存在作业。
	HasDependency bool
	// DependencyID 是依赖作业号。依赖成功且结果归档后，其总和会作为一个
	// 额外整数（追加在序列末尾）参与本次计算。
	DependencyID uint64
	// Dependencies 为有序的直接上游作业号列表（提交顺序即追加顺序）。
	// 列表中的作业全部成功且归档完整后，本作业才可运行；各上游的总和按
	// 列表顺序逐个追加到原始序列末尾，再计算总和与平方和——不会按上游
	// 完成先后改变输入。列表只能引用提交时已经存在的作业，不能包含零或
	// 重复作业号；与 HasDependency 同时填写非空列表会被拒绝。空列表
	// 表示无依赖，单依赖方式继续可用（单依赖与只含同一作业号的列表等价）。
	Dependencies []uint64
}

// Job 是作业元数据与结果的只读视图。
//
// 所有切片都是内部数据的拷贝，调用方修改返回的 [Job]（含其 [Archive]）
// 不会影响归档内部状态，也不会改变已保存的记录。
type Job struct {
	// ID 为稳定作业号，接受提交后分配，终身不变。
	ID uint64
	// Submitter 为提交人。
	Submitter string
	// RequestID 为幂等请求号。
	RequestID string
	// Seed 为提交时记录的种子。
	Seed int64
	// Values 为提交时记录的原始整数序列（保持原次序）。
	Values []int64
	// HasDependency / DependencyID 记录提交时指定的依赖。
	HasDependency bool
	DependencyID  uint64
	// Dependencies 为提交时记录的有序直接上游作业号（保持提交顺序）；
	// 无依赖时为空。单依赖方式提交的作业在此处表现为只含一个作业号。
	Dependencies []uint64
	// PendingDependencies 仅在排队时有意义：列出尚未成功归档的直接上游
	// 作业号，保持提交时的顺序；为空表示依赖已全部就绪（或本作业无依赖），
	// 排队原因随之变为等待计算位置。
	PendingDependencies []uint64

	// QueuedAt 为接受提交时记录的时间，仅用于时间范围过滤；列举结果的
	// 排列以接受先后（作业号）为准，时钟回拨导致的记录时间早晚不影响次序。
	QueuedAt time.Time
	// StartedAt 为进入运行状态的时间；未运行过为零值。
	StartedAt time.Time
	// FinishedAt 为进入终态（成功/失败/取消）的时间。
	FinishedAt time.Time

	// Status 为当前状态。
	Status Status
	// WaitReason 仅在 Status == StatusQueued 时有意义，说明排队原因。
	WaitReason WaitReason
	// FailureReason 仅在失败时有意义，说明失败原因（含阻断它的上游作业号）。
	FailureReason string
	// BlockerID 在因上游失败/取消而失败时，指出阻断链条的根因作业号；0 表示无。
	BlockerID uint64

	// EffectiveValues 为实际参与计算的输入（成功时）：
	// 原始序列末尾追加依赖作业的总和（若有依赖且其结果已归档）。
	EffectiveValues []int64

	// Archive 仅在 Status == StatusSucceeded 时非空，为完整成功归档。
	Archive *Archive
}

// Archive 是成功作业的完整归档记录：原始参数、实际参与计算的输入摘要、
// 结果摘要、计算日志与校验值。成功状态与归档在同一次原子落盘中可见。
type Archive struct {
	// JobID 为所属作业号。
	JobID uint64 `json:"job_id"`

	// 原始提交参数。
	Submitter string `json:"submitter"`
	RequestID string `json:"request_id"`
	// IdentityRaw 与 jobRecord 同义：标识含非法 UTF-8 字节时按完整字节
	// 保真，保证重开归档后归档中的提交人、请求号与提交时逐字节一致。
	IdentityRaw   *identityRaw `json:"identity_raw,omitempty"`
	Seed          int64        `json:"seed"`
	Values        []int64      `json:"values"`
	HasDependency bool         `json:"has_dependency"`
	DependencyID  uint64       `json:"dependency_id"`
	// Dependencies 为有序直接上游作业号（保持提交顺序）；单依赖方式提交的
	// 作业此处只含一个作业号。上游作业号不参与摘要与校验值。
	Dependencies []uint64 `json:"dependencies,omitempty"`

	// 实际参与计算的输入摘要。
	// EffectiveValues 为实际输入序列（原始序列 + 追加的依赖总和）。
	// InputsDigest 为其与种子的确定性摘要，与作业号、时间无关。
	EffectiveValues []int64 `json:"effective_values"`
	InputsDigest    string  `json:"inputs_digest"`

	// 结果摘要。
	Sum          int64 `json:"sum"`            // 总和
	SumOfSquares int64 `json:"sum_of_squares"` // 平方和
	// ResultDigest 为有效输入、种子与结果的确定性摘要，与作业号、时间无关。
	ResultDigest string `json:"result_digest"`

	// Log 为人类可读的确定性计算日志（不含作业号与时间）。
	Log string `json:"log"`

	// Checksum 为归档校验值，只由有效输入、种子、结果与计算日志决定，
	// 相同有效输入与种子必然得到相同校验值，作业号及时间不影响它。
	Checksum string `json:"checksum"`

	// CompletedAt 为归档完成时间，不参与任何摘要与校验值。
	CompletedAt time.Time `json:"completed_at"`
}

