111		}
112	
113		// 不在失败链上的作业照常计算并成功归档。
114		ind := waitStatus(t, s, indep.ID, StatusSucceeded)
115		if ind.Archive == nil || ind.Archive.Sum != 5 {
116			t.Fatalf("unrelated job must still succeed: %+v", ind)
117		}
118	
119		// 按提交人列举也应看到传播后的同一状态，顺序仍为提交先后。
120		list, err := s.List("a", time.Time{}, time.Time{})
121		if err != nil {
122			t.Fatal(err)
123		}
124		wantStatus := map[uint64]Status{
125			up.ID: StatusFailed, child.ID: StatusFailed,
126			grand.ID: StatusFailed, indep.ID: StatusSucceeded,
127		}
128		if len(list) != 4 {
129			t.Fatalf("list len=%d want 4", len(list))
130		}
131		for i, j := range list {
