149			}
150		}
151	
152		// 重新打开同一归档：失败传播结果不丢失，上游依旧没有可用成功归档。
153		if err := s.Close(); err != nil {
154			t.Fatal(err)
155		}
156		s2, err := Open(dir)
157		if err != nil {
158			t.Fatal(err)
159		}
160		defer s2.Close()
161		for _, want := range []struct {
162			id      uint64
163			blocker uint64
164		}{
165			{up.ID, 0}, {child.ID, up.ID}, {grand.ID, up.ID},
166		} {
