175			t.Fatalf("disk record must stay running after failed cancel:\n%s", data)
176		}
177	
178		// 计算在两次取消请求之间成功完成。
179		makeArchiveWritable(t, s.Dir())
180		release(run.ID)
181		done := waitStatus(t, s, run.ID, StatusSucceeded)
182		if done.Archive == nil || done.Archive.Sum != 1 {
183			t.Fatalf("compute must still be allowed to succeed: %+v", done)
184		}
185		if _, err := s.Cancel(run.ID); !errors.Is(err, ErrNotCancellable) {
186			t.Fatalf("cancel after success: %v, want ErrNotCancellable", err)
187		}
