	omu.Lock()
	defer omu.Unlock()
	want := []uint64{1, 2, 3, 4}
	if len(*order) != 4 {
		t.Fatalf("order=%v", *order)
	}
	for i := range want {
		if (*order)[i] != want[i] {
			t.Fatalf("execution order %v, want %v", *order, want)
		}
	}
}

