1	package numeric
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// 本文件覆盖“带依赖的作业被接受后，重开归档时上游记录缺失”场景下的重复提交：
14	// 原请求重放必须继续指向恢复后已被改判为失败的原作业，而不是以“依赖作业不
15	// 存在”拒绝；内容变化仍按幂等冲突处理；与已接受请求无关的新请求维持原有的
16	// 拒绝语义。
17	
18	// reopenMissing 删除指定作业号的落盘记录后重新打开目录，模拟重开归档时部分
19	// 直接上游记录缺失。重开后的 Store 注册到测试清理。
20	func reopenMissing(t *testing.T, dir string, missing ...uint64) *Store {
21		t.Helper()
22		for _, id := range missing {
23			if err := os.Remove(filepath.Join(dir, jobFileName(id))); err != nil {
24				t.Fatalf("remove job %d: %v", id, err)
25			}
26		}
27		s, err := Open(dir)
28		if err != nil {
29			t.Fatalf("reopen: %v", err)
30		}
31		t.Cleanup(func() { _ = s.Close() })
32		return s
33	}
34	
35	func countJobFiles(t *testing.T, dir string) int {
36		t.Helper()
37		entries, err := os.ReadDir(dir)
38		if err != nil {
39			t.Fatal(err)
40		}
41		n := 0
42		for _, e := range entries {
43			if !e.IsDir() && strings.HasPrefix(e.Name(), "job-") && strings.HasSuffix(e.Name(), ".json") {
44				n++
45			}
46		}
47		return n
48	}
49	
50	func readOnDiskJobRecord(t *testing.T, dir string, id uint64) jobRecord {
51		t.Helper()
52		data, err := os.ReadFile(filepath.Join(dir, jobFileName(id)))
53		if err != nil {
54			t.Fatal(err)
55		}
56		var r jobRecord
57		if err := json.Unmarshal(data, &r); err != nil {
58			t.Fatal(err)
59		}
60		return r
61	}
62	
63	// assertFailedViewEqual 断言两次查询/重放返回的失败视图逐字段一致：失败状态、
64	// 原因、根因、全部已有时间、原始参数与有序依赖，且成功归档与实际输入均为空。
65	func assertFailedViewEqual(t *testing.T, label string, got, want *Job) {
66		t.Helper()
67		if got.ID != want.ID {
68			t.Fatalf("%s: ID=%d want %d", label, got.ID, want.ID)
69		}
70		if got.Status != StatusFailed || want.Status != StatusFailed {
71			t.Fatalf("%s: status=%s want %s", label, got.Status, want.Status)
72		}
73		if got.FailureReason != want.FailureReason {
74			t.Fatalf("%s: reason=%q want %q", label, got.FailureReason, want.FailureReason)
75		}
76		if got.BlockerID != want.BlockerID {
77			t.Fatalf("%s: blocker=%d want %d", label, got.BlockerID, want.BlockerID)
78		}
79		if !got.QueuedAt.Equal(want.QueuedAt) || !got.StartedAt.Equal(want.StartedAt) ||
80			!got.FinishedAt.Equal(want.FinishedAt) {
81			t.Fatalf("%s: times got (%s,%s,%s) want (%s,%s,%s)", label,
82				got.QueuedAt, got.StartedAt, got.FinishedAt,
83				want.QueuedAt, want.StartedAt, want.FinishedAt)
84		}
85		if got.Archive != nil || got.EffectiveValues != nil {
86			t.Fatalf("%s: failed view must carry no archive/effective values, got archive=%v eff=%v",
87				label, got.Archive != nil, got.EffectiveValues)
88		}
89		if len(got.Values) != len(want.Values) {
90			t.Fatalf("%s: values=%v want %v", label, got.Values, want.Values)
91		}
92		for i := range want.Values {
93			if got.Values[i] != want.Values[i] {
94				t.Fatalf("%s: values=%v want %v", label, got.Values, want.Values)
95			}
96		}
97		if len(got.Dependencies) != len(want.Dependencies) {
98			t.Fatalf("%s: deps=%v want %v", label, got.Dependencies, want.Dependencies)
99		}
100		for i := range want.Dependencies {
101			if got.Dependencies[i] != want.Dependencies[i] {
102				t.Fatalf("%s: deps=%v want %v", label, got.Dependencies, want.Dependencies)
103			}
104		}
105	}
106	
107	// 单直接上游的作业曾成功归档；删除上游记录重开后，原作业因“成功结果不可用”
108	// 被改判为失败。用与已接受请求完全相同的请求（列表写法与单依赖写法互换都算
109	// 相同内容）再次提交：返回原作业的当前失败详情、无错误，不建作业、不补建
110	// 上游、不重新排队、不改写记录。
111	func TestReplayIdenticalRequestAfterUpstreamRecordMissing(t *testing.T) {
112		listReq := func(up uint64) SubmitRequest {
113			return SubmitRequest{
114				Submitter: "a", RequestID: "r", Values: []int64{5},
115				Dependencies: []uint64{up},
116			}
117		}
118		singleReq := func(up uint64) SubmitRequest {
119			return SubmitRequest{
120				Submitter: "a", RequestID: "r", Values: []int64{5},
121				HasDependency: true, DependencyID: up,
122			}
123		}
124		cases := []struct {
125			name         string
126			orig, replay func(up uint64) SubmitRequest
127		}{
128			{"list then list", listReq, listReq},
129			{"single then list", singleReq, listReq},
130			{"list then single", listReq, singleReq},
131			{"single then single", singleReq, singleReq},
132		}
133		for _, c := range cases {
134			t.Run(c.name, func(t *testing.T) {
135				dir := t.TempDir()
136				s, err := Open(dir)
137				if err != nil {
138					t.Fatal(err)
139				}
140				up := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "up", Values: []int64{4}})
141				waitStatus(t, s, up.ID, StatusSucceeded)
142				origReq := c.orig(up.ID)
143				orig := mustSubmit(t, s, origReq)
144				done := waitStatus(t, s, orig.ID, StatusSucceeded) // 实际输入 [5,4]
145				if len(done.Archive.EffectiveValues) != 2 || done.Archive.EffectiveValues[1] != 4 {
146					t.Fatalf("effective=%v want [5 4]", done.Archive.EffectiveValues)
147				}
148				if err := s.Close(); err != nil {
149					t.Fatal(err)
150				}
151	
152				s2 := reopenMissing(t, dir, up.ID)
153	
154				g0, err := s2.Get(orig.ID)
155				if err != nil {
156					t.Fatal(err)
157				}
158				if g0.Status != StatusFailed || g0.BlockerID != up.ID {
159					t.Fatalf("reopen status=%s blocker=%d want failed/root %d (reason=%q)",
160						g0.Status, g0.BlockerID, up.ID, g0.FailureReason)
161				}
162				if !strings.Contains(g0.FailureReason, "作业 "+itoa(up.ID)) ||
163					!strings.Contains(g0.FailureReason, "成功结果不可用") {
164					t.Fatalf("failure reason must name missing upstream: %q", g0.FailureReason)
165				}
166				if g0.Archive != nil || g0.EffectiveValues != nil || g0.FinishedAt.IsZero() || g0.StartedAt.IsZero() {
167					t.Fatalf("failed restore must clear archive/inputs and keep timestamps: %+v", g0)
168				}
169	
170				before := countJobFiles(t, dir)
171	
172				// 完全相同的原请求再次提交：返回原作业当前详情，无错误。
173				got, err := s2.Submit(c.replay(up.ID))
174				if err != nil {
175					t.Fatalf("identical replay after upstream missing: %v", err)
176				}
177				if got == nil {
178					t.Fatal("replay returned nil job")
179				}
180				assertFailedViewEqual(t, "replay", got, g0)
181	
182				// 不创建新作业，不补建缺失上游。
183				if countJobFiles(t, dir) != before {
184					t.Fatalf("replay changed on-disk record count: before=%d after=%d",
185						before, countJobFiles(t, dir))
186				}
187				if _, err := s2.Get(up.ID); !errors.Is(err, ErrNotFound) {
188					t.Fatalf("missing upstream recreated? err=%v want ErrNotFound", err)
189				}
190				if _, err := os.Stat(filepath.Join(dir, jobFileName(up.ID))); !os.IsNotExist(err) {
191					t.Fatalf("missing upstream file reappeared: %v", err)
192				}
193	
194				// 不把失败作业重新排队、不改写失败记录：稍等后状态/时间/原因不变。
195				time.Sleep(20 * time.Millisecond)
196				g1, _ := s2.Get(orig.ID)
197				assertFailedViewEqual(t, "after wait", g1, g0)
198				rec := readOnDiskJobRecord(t, dir, orig.ID)
199				if rec.Status != StatusFailed || rec.BlockerID != up.ID ||
200					rec.FailureReason != g0.FailureReason ||
201					!rec.FinishedAt.Equal(g0.FinishedAt) || !rec.QueuedAt.Equal(g0.QueuedAt) ||
202					len(rec.Dependencies) != 1 || rec.Dependencies[0] != up.ID ||
203					len(rec.Values) != 1 || rec.Values[0] != 5 {
204					t.Fatalf("on-disk original record altered by replay: %+v", rec)
205				}
206	
207				// 后续真正的新提交取得新作业号，缺失作业号也未被占用。
208				fresh := mustSubmit(t, s2, SubmitRequest{Submitter: "a", RequestID: "fresh", Values: []int64{1}})
209				if fresh.ID != orig.ID+1 {
210					t.Fatalf("new job id=%d want %d", fresh.ID, orig.ID+1)
211				}
212				waitStatus(t, s2, fresh.ID, StatusSucceeded)
213			})
214		}
215	}
216	
217	// 多个直接上游中只缺失其中一个时同样适用：按保存的依赖顺序最靠前的缺失上游
218	// 决定失败归因；原请求重放仍返回原作业。依赖次序变化或改成单依赖写法则属于
219	// 内容不一致，即使请求仍引用缺失上游也返回幂等冲突并指出缺失作业号。
220	func TestReplayMultiDependencyWithOneUpstreamMissing(t *testing.T) {
221		dir := t.TempDir()
222		s, err := Open(dir)
223		if err != nil {
224			t.Fatal(err)
225		}
226		up1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u1", Values: []int64{4}})
227		up2 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u2", Values: []int64{10}})
228		waitStatus(t, s, up1.ID, StatusSucceeded)
229		waitStatus(t, s, up2.ID, StatusSucceeded)
230		orig := mustSubmit(t, s, SubmitRequest{
231			Submitter: "a", RequestID: "r", Values: []int64{1},
232			Dependencies: []uint64{up1.ID, up2.ID},
233		})
234		waitStatus(t, s, orig.ID, StatusSucceeded) // 实际输入 [1,4,10]
235		if err := s.Close(); err != nil {
236			t.Fatal(err)
237		}
238	
239		// 只缺失依赖列表中更靠前的 up1。
240		s2 := reopenMissing(t, dir, up1.ID)
241	
242		g0, _ := s2.Get(orig.ID)
243		if g0.Status != StatusFailed || g0.BlockerID != up1.ID {
244			t.Fatalf("status=%s blocker=%d want failed/root %d (reason=%q)",
245				g0.Status, g0.BlockerID, up1.ID, g0.FailureReason)
246		}
247		if !strings.Contains(g0.FailureReason, "作业 "+itoa(up1.ID)) {
248			t.Fatalf("reason must name earliest missing upstream %d: %q", up1.ID, g0.FailureReason)
249		}
250		// 另一个上游保持自己的成功结果。
251		gUp2, _ := s2.Get(up2.ID)
252		if gUp2.Status != StatusSucceeded {
253			t.Fatalf("surviving upstream status=%s want succeeded", gUp2.Status)
254		}
255	
256		// 完全相同（多依赖列表）→ 原作业，无错误。
257		got, err := s2.Submit(SubmitRequest{
258			Submitter: "a", RequestID: "r", Values: []int64{1},
259			Dependencies: []uint64{up1.ID, up2.ID},
260		})
261		if err != nil {
262			t.Fatalf("identical multi-dep replay: %v", err)
263		}
264		assertFailedViewEqual(t, "multi-dep replay", got, g0)
265	
266		// 依赖次序变化 → 幂等冲突（不是“依赖不存在”），视图仍指原作业，
267		// 且明确说明内容不一致并指出仍被引用的缺失上游。
268		swapped, err := s2.Submit(SubmitRequest{
269			Submitter: "a", RequestID: "r", Values: []int64{1},
270			Dependencies: []uint64{up2.ID, up1.ID},
271		})
272		if !errors.Is(err, ErrIdempotencyConflict) || swapped == nil || swapped.ID != orig.ID {
273			t.Fatalf("order change: job=%v err=%v want ErrIdempotencyConflict + original job", swapped, err)
274		}
275		if !strings.Contains(err.Error(), "不一致") ||
276			!strings.Contains(err.Error(), "作业 "+itoa(up1.ID)) ||
277			!strings.Contains(err.Error(), "记录已缺失") {
278			t.Fatalf("conflict error must state mismatch and missing upstream %d: %q", up1.ID, err.Error())
279		}
280	
281		// 改成只含一个上游的单依赖写法 → 依赖内容不同，同样冲突。
282		single, err := s2.Submit(SubmitRequest{
283			Submitter: "a", RequestID: "r", Values: []int64{1},
284			HasDependency: true, DependencyID: up1.ID,
285		})
286		if !errors.Is(err, ErrIdempotencyConflict) || single == nil || single.ID != orig.ID {
287			t.Fatalf("single-dep rewrite vs 2-dep list must conflict: job=%v err=%v", single, err)
288		}
289		if !strings.Contains(err.Error(), "作业 "+itoa(up1.ID)) {
290			t.Fatalf("conflict error must still name missing upstream: %q", err.Error())
291		}
292	
293		// 冲突不改写原记录。
294		g1, _ := s2.Get(orig.ID)
295		assertFailedViewEqual(t, "after conflicts", g1, g0)
296	}
297	
298	// 同人同号下改变整数内容/次序或种子，即使请求仍引用已经缺失的上游，也返回
299	// 幂等冲突与原作业详情，明确告知内容不一致；原记录保持原样。
300	func TestReplayContentConflictAfterUpstreamRecordMissing(t *testing.T) {
301		dir := t.TempDir()
302		s, err := Open(dir)
303		if err != nil {
304			t.Fatal(err)
305		}
306		up := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "up", Values: []int64{4}})
307		waitStatus(t, s, up.ID, StatusSucceeded)
308		orig := mustSubmit(t, s, SubmitRequest{
309			Submitter: "a", RequestID: "r", Values: []int64{1, 2}, Seed: 7,
310			Dependencies: []uint64{up.ID},
311		})
312		waitStatus(t, s, orig.ID, StatusSucceeded)
313		if err := s.Close(); err != nil {
314			t.Fatal(err)
315		}
316		s2 := reopenMissing(t, dir, up.ID)
317		g0, _ := s2.Get(orig.ID)
318		if g0.Status != StatusFailed {
319			t.Fatalf("status=%s want failed", g0.Status)
320		}
321	
322		conflicts := []struct {
323			name string
324			req  SubmitRequest
325			// noteMissing 表示这次冲突请求仍引用缺失上游，错误中必须指出它。
326			noteMissing bool
327		}{
328			{
329				name:        "values content changed",
330				req:         SubmitRequest{Submitter: "a", RequestID: "r", Values: []int64{1, 3}, Seed: 7, Dependencies: []uint64{up.ID}},
331				noteMissing: true,
332			},
333			{
334				name:        "values order changed",
335				req:         SubmitRequest{Submitter: "a", RequestID: "r", Values: []int64{2, 1}, Seed: 7, Dependencies: []uint64{up.ID}},
336				noteMissing: true,
337			},
338			{
339				name:        "seed changed",
340				req:         SubmitRequest{Submitter: "a", RequestID: "r", Values: []int64{1, 2}, Seed: 8, Dependencies: []uint64{up.ID}},
341				noteMissing: true,
342			},
343			{
344				name:        "dependency dropped",
345				req:         SubmitRequest{Submitter: "a", RequestID: "r", Values: []int64{1, 2}, Seed: 7},
346				noteMissing: false,
347			},
348		}
349		for _, c := range conflicts {
350			t.Run(c.name, func(t *testing.T) {
351				j, err := s2.Submit(c.req)
352				if !errors.Is(err, ErrIdempotencyConflict) {
353					t.Fatalf("err=%v want ErrIdempotencyConflict", err)
354				}
355				if j == nil || j.ID != orig.ID {
356					t.Fatalf("conflict must return original job view: %+v", j)
357				}
358				assertFailedViewEqual(t, "conflict view", j, g0)
359				if !strings.Contains(err.Error(), "不一致") {
360					t.Fatalf("conflict error must state content mismatch: %q", err.Error())
361				}
362				if c.noteMissing {
363					if !strings.Contains(err.Error(), "作业 "+itoa(up.ID)) ||
364						!strings.Contains(err.Error(), "记录已缺失") {
365						t.Fatalf("conflict error must name still-referenced missing upstream %d: %q",
366							up.ID, err.Error())
367					}
368				} else if strings.Contains(err.Error(), "记录已缺失") {
369					t.Fatalf("request without missing upstream must not carry missing note: %q", err.Error())
370				}
371			})
372		}
373	
374		// 依赖改挂到另一个仍存在的作业：同样只是冲突，且不产生缺失提示、不补建上游。
375		other := mustSubmit(t, s2, SubmitRequest{Submitter: "a", RequestID: "other", Values: []int64{9}})
376		waitStatus(t, s2, other.ID, StatusSucceeded)
377		j, err := s2.Submit(SubmitRequest{
378			Submitter: "a", RequestID: "r", Values: []int64{1, 2}, Seed: 7,
379			Dependencies: []uint64{other.ID},
380		})
381		if !errors.Is(err, ErrIdempotencyConflict) || j == nil || j.ID != orig.ID {
382			t.Fatalf("dep swap to existing job must still conflict: job=%v err=%v", j, err)
383		}
384		if strings.Contains(err.Error(), "记录已缺失") {
385			t.Fatalf("rewrite referencing only existing jobs must not carry missing note: %q", err.Error())
386		}
387	
388		// 全部冲突之后，失败记录的状态、原因、根因、时间、原始参数与依赖原样保留。
389		g1, _ := s2.Get(orig.ID)
390		assertFailedViewEqual(t, "final", g1, g0)
391		if _, err := s2.Get(up.ID); !errors.Is(err, ErrNotFound) {
392			t.Fatalf("missing upstream must stay missing: %v", err)
393		}
394	}
395	
396	// 提交人不同、请求号不同或请求号为空的提交不命中幂等记录：引用缺失上游时
397	// 仍按新请求拒绝（ErrDependencyNotFound），不产生记录，也不占用请求号。
398	func TestNewRequestReferencingMissingUpstreamStillRejected(t *testing.T) {
399		dir := t.TempDir()
400		s, err := Open(dir)
401		if err != nil {
402			t.Fatal(err)
403		}
404		up := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "up", Values: []int64{4}})
405		waitStatus(t, s, up.ID, StatusSucceeded)
406		orig := mustSubmit(t, s, SubmitRequest{
407			Submitter: "a", RequestID: "r", Values: []int64{5},
408			Dependencies: []uint64{up.ID},
409		})
410		waitStatus(t, s, orig.ID, StatusSucceeded)
411		if err := s.Close(); err != nil {
412			t.Fatal(err)
413		}
414		s2 := reopenMissing(t, dir, up.ID)
415		before := countJobFiles(t, dir) // 只剩原作业一条记录
416	
417		newRequests := []struct {
418			name string
419			req  SubmitRequest
420		}{
421			{"different submitter same request id", SubmitRequest{
422				Submitter: "b", RequestID: "r", Values: []int64{5},
423				Dependencies: []uint64{up.ID},
424			}},
425			{"same submitter different request id", SubmitRequest{
426				Submitter: "a", RequestID: "r2", Values: []int64{5},
427				Dependencies: []uint64{up.ID},
428			}},
429			{"empty request id", SubmitRequest{
430				Submitter: "a", Values: []int64{5},
431				Dependencies: []uint64{up.ID},
432			}},
433			{"single-dep form", SubmitRequest{
434				Submitter: "a", RequestID: "r3", Values: []int64{5},
435				HasDependency: true, DependencyID: up.ID,
436			}},
437		}
438		for _, c := range newRequests {
439			t.Run(c.name, func(t *testing.T) {
440				j, err := s2.Submit(c.req)
441				if !errors.Is(err, ErrDependencyNotFound) {
442					t.Fatalf("err=%v want ErrDependencyNotFound", err)
443				}
444				if j != nil {
445					t.Fatalf("rejected submit must not return a job: %+v", j)
446				}
447				if countJobFiles(t, dir) != before {
448					t.Fatalf("rejected submit created a record (files %d != %d)",
449						countJobFiles(t, dir), before)
450				}
451			})
452		}
453	
454		// 不同提交人被拒绝后不产生其名下记录。
455		if listed, err := s2.List("b", time.Time{}, time.Time{}); err != nil || len(listed) != 0 {
456			t.Fatalf("rejected different-submitter submit left records: %v err=%v", listed, err)
457		}
458		// 被拒绝的请求号未被占用：同号提交改为引用合法内容（无依赖）应作为新作业接受。
459		reuse := mustSubmit(t, s2, SubmitRequest{Submitter: "a", RequestID: "r2", Values: []int64{3}})
460		if reuse.ID != orig.ID+1 {
461			t.Fatalf("reused request id created job %d, want fresh id %d", reuse.ID, orig.ID+1)
462		}
463		waitStatus(t, s2, reuse.ID, StatusSucceeded)
464		// 缺失上游始终未被补建，原失败作业也未被改动。
465		if _, err := s2.Get(up.ID); !errors.Is(err, ErrNotFound) {
466			t.Fatalf("missing upstream recreated: %v", err)
467		}
468		g, _ := s2.Get(orig.ID)
469		if g.Status != StatusFailed || g.BlockerID != up.ID {
470			t.Fatalf("original job altered: status=%s blocker=%d", g.Status, g.BlockerID)
471		}
472	}
473	
474	// 请求自身的格式错误先于幂等判定：即使提交人+请求号正好命中已接受请求，
475	// 空整数序列、依赖号为零、重复依赖、两种写法同时启用仍返回原有对应拒绝，
476	// 不返回原作业，也不改写原记录。
477	func TestReplayStructuralValidationPrecedesIdempotency(t *testing.T) {
478		dir := t.TempDir()
479		s, err := Open(dir)
480		if err != nil {
481			t.Fatal(err)
482		}
483		up := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "up", Values: []int64{4}})
484		waitStatus(t, s, up.ID, StatusSucceeded)
485		orig := mustSubmit(t, s, SubmitRequest{
486			Submitter: "a", RequestID: "r", Values: []int64{5},
487			Dependencies: []uint64{up.ID},
488		})
489		waitStatus(t, s, orig.ID, StatusSucceeded)
490		if err := s.Close(); err != nil {
491			t.Fatal(err)
492		}
493		// 上游缺失下重放：结构校验必须仍然先于“上游不存在”与幂等判定。
494		s2 := reopenMissing(t, dir, up.ID)
495		g0, _ := s2.Get(orig.ID)
496	
497		cases := []struct {
498			name string
499			req  SubmitRequest
500			want error
501		}{
502			{"empty sequence", SubmitRequest{
503				Submitter: "a", RequestID: "r", Dependencies: []uint64{up.ID},
504			}, ErrEmptySequence},
505			{"zero dependency", SubmitRequest{
506				Submitter: "a", RequestID: "r", Values: []int64{5},
507				HasDependency: true, DependencyID: 0,
508			}, ErrInvalidDependency},
509			{"duplicate dependency", SubmitRequest{
510				Submitter: "a", RequestID: "r", Values: []int64{5},
511				Dependencies: []uint64{up.ID, up.ID},
512			}, ErrInvalidDependency},
513			{"both dependency forms", SubmitRequest{
514				Submitter: "a", RequestID: "r", Values: []int64{5},
515				HasDependency: true, DependencyID: up.ID,
516				Dependencies: []uint64{up.ID},
517			}, ErrInvalidDependency},
518		}
519		for _, c := range cases {
520			t.Run(c.name, func(t *testing.T) {
521				j, err := s2.Submit(c.req)
522				if !errors.Is(err, c.want) {
523					t.Fatalf("err=%v want %v", err, c.want)
524				}
525				if j != nil {
526					t.Fatalf("structural rejection must not return a job: %+v", j)
527				}
528			})
529		}
530		g1, _ := s2.Get(orig.ID)
531		assertFailedViewEqual(t, "original after structural rejections", g1, g0)
532	}
533	
534	// 归档关闭后，原请求重放同样返回归档已关闭。
535	func TestReplayAfterArchiveClosed(t *testing.T) {
536		dir := t.TempDir()
537		s, err := Open(dir)
538		if err != nil {
539			t.Fatal(err)
540		}
541		up := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "up", Values: []int64{4}})
542		waitStatus(t, s, up.ID, StatusSucceeded)
543		orig := mustSubmit(t, s, SubmitRequest{
544			Submitter: "a", RequestID: "r", Values: []int64{5},
545			Dependencies: []uint64{up.ID},
546		})
547		waitStatus(t, s, orig.ID, StatusSucceeded)
548		if err := s.Close(); err != nil {
549			t.Fatal(err)
550		}
551		// 上游记录同时缺失：关闭检查最先生效，无论内容如何都返回 ErrStoreClosed。
552		if err := os.Remove(filepath.Join(dir, jobFileName(up.ID))); err != nil {
553			t.Fatal(err)
554		}
555		s2, err := Open(dir)
556		if err != nil {
557			t.Fatal(err)
558		}
559		if err := s2.Close(); err != nil {
560			t.Fatal(err)
561		}
562		if _, err := s2.Submit(SubmitRequest{
563			Submitter: "a", RequestID: "r", Values: []int64{5},
564			Dependencies: []uint64{up.ID},
565		}); !errors.Is(err, ErrStoreClosed) {
566			t.Fatalf("closed-store replay err=%v want ErrStoreClosed", err)
567		}
568	}
